def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        return None

    x_mean = sum(numbers) / len(numbers)
    MAD = sum(abs(x - x_mean) for x in numbers) / len(numbers)
    return MAD

def max_value_on_paths(N, grid_values):
    # Initialize the dynamic programming table
    dp = [[0] * N for _ in range(N)]

    # Fill in the values for the first row and column
    for i in range(N):
        x, y, val = grid_values[i]
        dp[x][y] = val

    # Fill in the rest of the table
    for i in range(1, N):
        for j in range(1, N):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + dp[i][j]

    # Return the maximum value in the bottom-right corner
    return dp[N - 1][N - 1]

